"""Observability for one engine turn.

The turn lifecycle records voice span attributes and emits the
channel-neutral ``rasa.turn.*`` metrics from the turn context's calculations.
"""

from __future__ import annotations

import asyncio
from contextlib import contextmanager
from contextvars import ContextVar
from typing import Iterator, Optional

from opentelemetry import trace
from opentelemetry.trace import Span

from rasa.tracing.turn import (
    TurnObservabilityContext,
    TurnOutcome,
    TurnOutputModality,
    bind_turn_observability_context,
    get_current_turn_input_anchor,
    record_turn_duration_metric,
    record_turn_time_to_first_output_metric,
)
from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.shared.context import (
    get_current_call_observability_context,
)
from rasa.tracing.voice.spans import (
    content_capture_enabled,
    voice_call_context,
    voice_stage_span,
)

# ---------------------------------------------------------------------------
# Recorder
# ---------------------------------------------------------------------------


class HandleTurnRecorder:
    """Record attributes on one engine turn's voice `handle turn` span.

    A detached recorder does not record attributes.
    """

    def __init__(self, span: Span) -> None:
        self.span = span

    @classmethod
    def detached(cls) -> "HandleTurnRecorder":
        """Return a recorder without a span, e.g. for turns outside a call."""
        return cls(trace.INVALID_SPAN)

    def record_rasa_processing_ms(self, rasa_processing_ms: Optional[float]) -> None:
        """Stamp the whole-turn Rasa processing time, skipping unknown values.

        Args:
            rasa_processing_ms: Whole-turn Rasa processing time in ms.
        """
        if rasa_processing_ms is not None and self.span.is_recording():
            self.span.set_attribute(
                semconv.VOICE_LATENCY_RASA_PROCESSING_MS, rasa_processing_ms
            )

    def record_user_perceived_ms(self, user_perceived_ms: Optional[float]) -> None:
        """Stamp the user-perceived latency, skipping unknown values.

        Args:
            user_perceived_ms: Milliseconds from the user's input to the
                first output the user perceives.
        """
        if user_perceived_ms is not None and self.span.is_recording():
            self.span.set_attribute(
                semconv.VOICE_LATENCY_USER_PERCEIVED_MS, user_perceived_ms
            )

    def record_interrupted(self) -> None:
        """Record that the turn was interrupted."""
        if self.span.is_recording():
            self.span.set_attribute(semconv.VOICE_INTERRUPTED, True)

    def record_response_dropped(
        self,
        *,
        text: Optional[str] = None,
        is_filler: bool = False,
    ) -> None:
        """Record a generated agent message that cancellation dropped before commit.

        Args:
            text: Dropped text, included only when content capture is enabled.
            is_filler: Whether the message was a filler rather than a full response.
        """
        if not self.span.is_recording():
            return
        attributes: dict = {
            semconv.RASA_TURN_RESPONSE_DROPPED_IS_FILLER: is_filler,
        }
        if text is not None and content_capture_enabled():
            attributes[semconv.RASA_TURN_RESPONSE_DROPPED_TEXT] = text
        self.span.add_event(semconv.EVENT_RESPONSE_DROPPED, attributes)

    def record_filler_sent(
        self,
        *,
        response_name: Optional[str] = None,
        text: Optional[str] = None,
    ) -> None:
        """Record that a filler message was sent during this turn.

        Args:
            response_name: Response/template name of the filler (e.g.
                ``utter_ack_processing``); absent for LLM-generated fillers.
            text: The filler text. Stamped only when content capture is
                enabled (``RASA_VOICE_CAPTURE_CONTENT``).
        """
        if not self.span.is_recording():
            return
        attributes = {}
        if response_name is not None:
            attributes[semconv.VOICE_FILLER_RESPONSE_NAME] = response_name
        if text is not None and content_capture_enabled():
            attributes[semconv.VOICE_FILLER_TEXT] = text
        self.span.add_event(semconv.EVENT_FILLER_SENT, attributes)


# ---------------------------------------------------------------------------
# Context bindings
# ---------------------------------------------------------------------------


_current_handle_turn_recorder: ContextVar[Optional[HandleTurnRecorder]] = ContextVar(
    "rasa_voice_current_handle_turn", default=None
)


@contextmanager
def bind_handle_turn_recorder(
    turn_recorder: HandleTurnRecorder,
) -> Iterator[HandleTurnRecorder]:
    """Bind ``turn_recorder`` as the active turn recorder, unbinding on exit."""
    token = _current_handle_turn_recorder.set(turn_recorder)
    try:
        yield turn_recorder
    finally:
        _current_handle_turn_recorder.reset(token)


# ---------------------------------------------------------------------------
# Accessors
# ---------------------------------------------------------------------------


def get_current_handle_turn_recorder() -> HandleTurnRecorder:
    """Return the active turn recorder or a detached no-op recorder."""
    current_turn_recorder = _current_handle_turn_recorder.get()
    if current_turn_recorder is not None:
        return current_turn_recorder
    return HandleTurnRecorder.detached()


# ---------------------------------------------------------------------------
# Turn lifecycle
# ---------------------------------------------------------------------------


@contextmanager
def handle_turn_span() -> Iterator[HandleTurnRecorder]:
    """Open a `handle turn` span for one engine turn of the active voice call.

    Signal behavior:

    - Tracing enabled: re-attaches the call context so the span remains part
      of the call trace.
    - Metrics only: binds turn state without recording a span.
    - No active voice call: yields a detached recorder — no span, but the
      channel-neutral ``rasa.turn.*`` metrics still measure the turn.

    Yields:
        The turn's typed recorder (no-op when tracing is unconfigured).
    """
    anchor = get_current_turn_input_anchor()
    observability = get_current_call_observability_context()
    if observability is None:
        # TODO(ENG-3003): Unify this with the channel-agnostic `rasa.turn` span.
        turn_observability = TurnObservabilityContext.from_input_anchor(
            anchor,
            output_modality=TurnOutputModality.TEXT,
        )
        with bind_turn_observability_context(turn_observability):
            yield from _finalized_turn(
                turn_observability, HandleTurnRecorder.detached()
            )
        return

    turn_observability = observability.begin_turn(anchor)
    try:
        with voice_call_context():
            with voice_stage_span(
                semconv.SPAN_NAME_HANDLE_TURN,
                attributes={semconv.VOICE_TURN_INDEX: turn_observability.index},
            ) as span:
                turn_recorder = HandleTurnRecorder(span)
                try:
                    with bind_handle_turn_recorder(turn_recorder):
                        yield from _finalized_turn(turn_observability, turn_recorder)
                finally:
                    # Record final attributes after all output and outcome signals.
                    turn_recorder.record_user_perceived_ms(
                        turn_observability.user_perceived_latency_ms
                    )
                    if turn_observability.interrupted:
                        turn_recorder.record_interrupted()
    finally:
        observability.end_turn()


# ---------------------------------------------------------------------------
# Private helpers
# ---------------------------------------------------------------------------


def _finalized_turn(
    turn_observability: TurnObservabilityContext, turn_recorder: HandleTurnRecorder
) -> Iterator[HandleTurnRecorder]:
    """Yield the recorder and record the turn's metrics exactly once.

    Before propagating an exception, record ``CancelledError`` as a cancellation
    and any other exception as an error. Metrics and span attributes use the
    resulting outcome from the turn context.
    """
    try:
        yield turn_recorder
    except asyncio.CancelledError:
        turn_observability.record_cancelled()
        raise
    except BaseException:
        turn_observability.record_error()
        raise
    finally:
        _record_turn_metrics(turn_observability, turn_observability.turn_outcome())


def _record_turn_metrics(
    turn_observability: TurnObservabilityContext, outcome: TurnOutcome
) -> None:
    """Emit the channel-neutral ``rasa.turn.*`` metrics for a finished turn.

    Records ``rasa.turn.duration`` for each eligible turn and
    ``rasa.turn.time_to_first_output`` only when the turn produced output in
    its output modality. Turns without an ``input_type`` emit nothing.
    """
    if turn_observability.input_type is None:
        return
    record_turn_duration_metric(
        turn_observability.calculate_turn_duration_seconds(),
        input_type=turn_observability.input_type,
        outcome=outcome,
    )
    time_to_first_output_s = turn_observability.calculate_time_to_first_output_seconds()
    if time_to_first_output_s is None or turn_observability.output_modality is None:
        return
    record_turn_time_to_first_output_metric(
        time_to_first_output_s,
        input_type=turn_observability.input_type,
        output_type=turn_observability.output_modality,
    )
